struct string_rep {
    char *data;
    int capacity;
    int length;
};

class stringx {
    int reserved;
    string_rep *rep;

public:
    int compare(const stringx &other) const
    {
        int count = rep->length < other.rep->length
                  ? rep->length : other.rep->length;
        for (int i = 0; i < count; ++i) {
            if (rep->data[i] < other.rep->data[i])
                return -1;
            if (other.rep->data[i] < rep->data[i])
                return 1;
        }
        if (rep->length < other.rep->length)
            return -1;
        if (other.rep->length < rep->length)
            return 1;
        return 0;
    }
};

template<class T1, class T2>
struct pair {
    T1 first;
    T2 second;
};

template<class Pair>
struct Select1st {
    const typename Pair::first_type &operator()(const Pair &value) const;
};

template<class T>
struct less {
    bool operator()(const T &left, const T &right) const
    {
        return left.compare(right) == -1;
    }
};

template<class T> class my_allocator {};

struct _Rb_tree_node_base {
    int color;
    _Rb_tree_node_base *parent;
    _Rb_tree_node_base *left;
    _Rb_tree_node_base *right;
};

template<class Value>
struct _Rb_tree_node : _Rb_tree_node_base {
    Value value_field;
};

template<class Key, class Value, class KeyOfValue, class Compare, class Alloc>
class _Rb_tree {
    typedef _Rb_tree_node<Value> *link_type;

public:
    struct iterator {
        link_type node;
        iterator() {}
        iterator(link_type value) : node(value) {}
        bool operator==(const iterator &other) const { return node == other.node; }
    };

private:
    link_type header;
    unsigned int node_count;
    Compare key_compare;

    link_type root() const { return (link_type) header->parent; }
    static link_type left(link_type node) { return (link_type) node->left; }
    static link_type right(link_type node) { return (link_type) node->right; }
    static const Key &key(link_type node) { return node->value_field.first; }

public:
    iterator find(const Key &search)
    {
        link_type y = header;
        link_type x = root();
        while (x != 0)
            if (!key_compare(key(x), search))
                y = x, x = left(x);
            else
                x = right(x);
        iterator j = iterator(y);
        iterator finish = iterator(header);
        return (j == finish || key_compare(search, key(j.node)))
             ? finish : j;
    }
};

template<>
struct pair<const stringx, short> {
    typedef const stringx first_type;
    const stringx first;
    short second;
};

template class _Rb_tree<
    stringx,
    pair<const stringx, short>,
    Select1st<pair<const stringx, short> >,
    less<stringx>,
    my_allocator<short>
>;
